export default {"file":"reportcards.html","title":"Report Card — Schoolix","htmlClass":"","bodyClass":"","body":"\r\n<div id=\"sxPageLoader\" class=\"sx-page-loader\" role=\"status\" aria-live=\"polite\">\r\n  <section class=\"dots-container\" aria-label=\"Loading page\">\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n  </section>\r\n</div>\r\n  <div class=\"container\">\r\n\r\n    <!-- Top bar -->\r\n    <div class=\"top-bar\">\r\n      <div class=\"brand\">\r\n        <div class=\"brand-mark\">\r\n          <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 10v6M2 10l10-5 10 5-10 5z\"/><path d=\"M6 12v5c3 3 9 3 12 0v-5\"/></svg>\r\n        </div>\r\n        <div>\r\n          <h1>Schoolix — Report Card Generator</h1>\r\n          <p class=\"subtitle\">Global subjects, session-aware report cards</p>\r\n        </div>\r\n      </div>\r\n      <a class=\"btn-back\" href=\"#/index.html\">\r\n        <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"19\" y1=\"12\" x2=\"5\" y2=\"12\"/><polyline points=\"12 19 5 12 12 5\"/></svg>\r\n        Back to Dashboard\r\n      </a>\r\n    </div>\r\n\r\n    <div class=\"layout\">\r\n      <!-- MAIN -->\r\n      <div>\r\n        <!-- Session -->\r\n        <div class=\"panel\">\r\n          <div class=\"panel-header\">\r\n            <div class=\"panel-title\">\r\n              <div class=\"icon-box\">\r\n                <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"4\" width=\"18\" height=\"18\" rx=\"2\"/><line x1=\"16\" y1=\"2\" x2=\"16\" y2=\"6\"/><line x1=\"8\" y1=\"2\" x2=\"8\" y2=\"6\"/><line x1=\"3\" y1=\"10\" x2=\"21\" y2=\"10\"/></svg>\r\n              </div>\r\n              <div>\r\n                <h3>Academic Session</h3>\r\n                <p>Select the session for this report card</p>\r\n              </div>\r\n            </div>\r\n          </div>\r\n          <div class=\"field\">\r\n            <label for=\"sessionSelector\">Session</label>\r\n            <select id=\"sessionSelector\" onchange=\"onSessionChange()\">\r\n              <option value=\"\">— Select Session —</option>\r\n            </select>\r\n          </div>\r\n          <div id=\"sessionLockBanner\" class=\"banner banner-warn\">\r\n            <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"11\" width=\"18\" height=\"11\" rx=\"2\"/><path d=\"M7 11V7a5 5 0 0 1 10 0v4\"/></svg>\r\n            This session is locked. Report cards are view-only.\r\n          </div>\r\n          <div id=\"sessionActiveBanner\" class=\"banner banner-ok\">\r\n            <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 11.08V12a10 10 0 1 1-5.93-9.14\"/><polyline points=\"22 4 12 14.01 9 11.01\"/></svg>\r\n            Active session selected.\r\n          </div>\r\n        </div>\r\n\r\n        <!-- Student search -->\r\n        <div class=\"panel\">\r\n          <div class=\"panel-header\">\r\n            <div class=\"panel-title\">\r\n              <div class=\"icon-box\">\r\n                <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"/></svg>\r\n              </div>\r\n              <div>\r\n                <h3>Student Search</h3>\r\n                <p>Fetch a student by their ID</p>\r\n              </div>\r\n            </div>\r\n          </div>\r\n          <div class=\"form-row\">\r\n            <div class=\"field\">\r\n              <label for=\"studentId\">Student ID</label>\r\n              <input id=\"studentId\" type=\"text\" placeholder=\"Enter student ID\" />\r\n            </div>\r\n            <div class=\"field\">\r\n              <label for=\"name\">Student Name</label>\r\n              <input id=\"name\" type=\"text\" placeholder=\"Auto-filled after fetch\" readonly />\r\n            </div>\r\n            <div class=\"field\">\r\n              <label for=\"class\">Class &amp; Section</label>\r\n              <input id=\"class\" type=\"text\" placeholder=\"Auto-filled after fetch\" readonly />\r\n            </div>\r\n          </div>\r\n          <div class=\"toolbar\" style=\"margin-top:16px;\">\r\n            <button class=\"btn btn-primary\" onclick=\"fetchStudent()\">\r\n              <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"7 10 12 15 17 10\"/><line x1=\"12\" y1=\"15\" x2=\"12\" y2=\"3\"/></svg>\r\n              Fetch Student\r\n            </button>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- Global subjects -->\r\n        <div class=\"panel\" id=\"subjectsCard\">\r\n          <div class=\"panel-header\">\r\n            <div class=\"panel-title\">\r\n              <div class=\"icon-box\">\r\n                <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"/><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"/></svg>\r\n              </div>\r\n              <div>\r\n                <h3>Global Subjects (School Level)</h3>\r\n                <p>Saved once, reusable for every student</p>\r\n              </div>\r\n            </div>\r\n            <div class=\"stat-chips\">\r\n              <span class=\"chip\"><svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 19.5A2.5 2.5 0 0 1 6.5 17H20\"/><path d=\"M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z\"/></svg><span id=\"subjectCount\">0 Subjects</span></span>\r\n              <span class=\"chip\"><svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 20V10M18 20V4M6 20v-4\"/></svg><span id=\"totalMarks\">0 Marks</span></span>\r\n              <span class=\"chip\"><svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"19\" y1=\"5\" x2=\"5\" y2=\"19\"/><circle cx=\"6.5\" cy=\"6.5\" r=\"2.5\"/><circle cx=\"17.5\" cy=\"17.5\" r=\"2.5\"/></svg><span id=\"avgMarks\">-- %</span></span>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"banner-info\">\r\n            <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\r\n            These subjects are saved at school level and can be used for any student.\r\n          </div>\r\n\r\n          <div class=\"subject-head\">\r\n            <span>Subject</span><span>Obtained</span><span>Max Marks</span><span></span>\r\n          </div>\r\n          <div id=\"subjects\"></div>\r\n\r\n          <div class=\"toolbar\">\r\n            <button class=\"btn btn-secondary\" onclick=\"addSubject()\">\r\n              <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg>\r\n              Add Subject\r\n            </button>\r\n            <button class=\"btn btn-success\" id=\"saveSubjectsBtn\" onclick=\"saveSubjects()\">\r\n              <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z\"/><polyline points=\"17 21 17 13 7 13 7 21\"/><polyline points=\"7 3 7 8 15 8\"/></svg>\r\n              Save Global Subjects\r\n            </button>\r\n            <button class=\"btn btn-info\" onclick=\"loadSubjects()\">\r\n              <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"23 4 23 10 17 10\"/><path d=\"M20.49 15a9 9 0 1 1-2.12-9.36L23 10\"/></svg>\r\n              Load Global Subjects\r\n            </button>\r\n            <button class=\"btn btn-danger\" id=\"deleteSubjectsBtn\" onclick=\"deleteAllGlobalSubjects()\">\r\n              <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"3 6 5 6 21 6\"/><path d=\"M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2\"/></svg>\r\n              Delete All Global\r\n            </button>\r\n          </div>\r\n          <div id=\"subjectsStatus\" class=\"status-msg\"></div>\r\n        </div>\r\n\r\n        <!-- Report actions -->\r\n        <div class=\"panel\">\r\n          <div class=\"panel-header\">\r\n            <div class=\"panel-title\">\r\n              <div class=\"icon-box\">\r\n                <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/><line x1=\"16\" y1=\"13\" x2=\"8\" y2=\"13\"/><line x1=\"16\" y1=\"17\" x2=\"8\" y2=\"17\"/></svg>\r\n              </div>\r\n              <div>\r\n                <h3>Report Card</h3>\r\n                <p>Generate, save, lock and print</p>\r\n              </div>\r\n            </div>\r\n          </div>\r\n          <div class=\"toolbar\">\r\n            <button class=\"btn btn-primary\" onclick=\"generateReport()\">\r\n              <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 20h9\"/><path d=\"M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4z\"/></svg>\r\n              Generate Report\r\n            </button>\r\n            <button class=\"btn btn-success\" id=\"saveReportBtn\" onclick=\"saveReportCard()\" disabled>\r\n              <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z\"/><polyline points=\"17 21 17 13 7 13 7 21\"/><polyline points=\"7 3 7 8 15 8\"/></svg>\r\n              Save Report Card\r\n            </button>\r\n            <button class=\"btn btn-warning\" id=\"lockReportBtn\" onclick=\"lockReportCard()\" disabled>\r\n              <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"11\" width=\"18\" height=\"11\" rx=\"2\"/><path d=\"M7 11V7a5 5 0 0 1 10 0v4\"/></svg>\r\n              Lock Report Card\r\n            </button>\r\n            <button class=\"btn btn-secondary\" onclick=\"printReport()\">\r\n              <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 6 2 18 2 18 9\"/><path d=\"M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2\"/><rect x=\"6\" y=\"14\" width=\"12\" height=\"8\"/></svg>\r\n              Print Report\r\n            </button>\r\n            <button class=\"btn btn-danger\" onclick=\"clearAll()\">\r\n              <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 6h18\"/><path d=\"M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2\"/><path d=\"M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6\"/></svg>\r\n              Clear All\r\n            </button>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- Report output -->\r\n        <div id=\"reportSection\"></div>\r\n      </div>\r\n\r\n      <!-- SIDEBAR -->\r\n      <aside>\r\n        <div class=\"panel\">\r\n          <div class=\"panel-header\">\r\n            <div class=\"panel-title\">\r\n              <div class=\"icon-box\">\r\n                <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"13 2 3 14 12 14 11 22 21 10 12 10 13 2\"/></svg>\r\n              </div>\r\n              <div>\r\n                <h3>Quick Actions</h3>\r\n                <p>Shortcuts</p>\r\n              </div>\r\n            </div>\r\n          </div>\r\n          <button class=\"btn btn-primary btn-block\" onclick=\"viewGeneratedReports()\">\r\n            <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg>\r\n            View All Reports\r\n          </button>\r\n        </div>\r\n\r\n        <div class=\"panel\">\r\n          <div class=\"panel-header\">\r\n            <div class=\"panel-title\">\r\n              <div class=\"icon-box\">\r\n                <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2l2.4 7.4H22l-6 4.6 2.3 7L12 16.9 5.7 21 8 14 2 9.4h7.6z\"/></svg>\r\n              </div>\r\n              <div>\r\n                <h3>Global Subjects</h3>\r\n                <p>Why use them</p>\r\n              </div>\r\n            </div>\r\n          </div>\r\n          <div class=\"side-list\">\r\n            <div class=\"side-feature\">\r\n              <span class=\"tick\"><svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></span>\r\n              <p>Save once, use for all students</p>\r\n            </div>\r\n            <div class=\"side-feature\">\r\n              <span class=\"tick\"><svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></span>\r\n              <p>School-level subject list</p>\r\n            </div>\r\n            <div class=\"side-feature\">\r\n              <span class=\"tick\"><svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></span>\r\n              <p>Delete all global subjects anytime</p>\r\n            </div>\r\n            <div class=\"side-feature\">\r\n              <span class=\"tick\"><svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></span>\r\n              <p>Best for a standard curriculum</p>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </aside>\r\n    </div>\r\n  </div>\r\n\r\n  <script type=\"module\">\r\n    import { initializeApp } from \"./firebase-compat.js\";\r\n    import { getFirestore, collection, getDocs, getDoc, doc, addDoc, updateDoc, deleteDoc, query, where, orderBy, serverTimestamp } from \"./firebase-compat.js\";\r\n    import { getAuth, onAuthStateChanged } from \"./firebase-compat.js\";\r\n\r\n    const firebaseConfig = {\r\n       apiKey: \"AIzaSyAomGwef93HFT9Xyx7SVW95FPw_IcIAICE\",\r\n      authDomain: \"schoolix-48107.firebaseapp.com\",\r\n      projectId: \"schoolix-48107\",\r\n      storageBucket: \"schoolix-48107.firebasestorage.app\",\r\n      messagingSenderId: \"133937954491\",\r\n      appId: \"1:133937954491:web:69d8064422617eb8c4339e\",\r\n      measurementId: \"G-EG23XE5Q0Z\"\r\n    };\r\n\r\n    const app = initializeApp(firebaseConfig);\r\n    const db = getFirestore(app);\r\n    const auth = getAuth(app);\r\n\r\n    let currentUser = null;\r\n    let currentStudent = null;\r\n    let unsubscribeSubjects = null;\r\n    let subjectsData = [];\r\n    let subjectsSaved = false;\r\n    let reportGenerated = false;\r\n    let lastGeneratedReportData = null;\r\n    let currentSession = \"\";\r\n    let currentSessionId = \"\";\r\n    let currentSessionLocked = false;\r\n    let currentReportCardId = null;\r\n\r\n    onAuthStateChanged(auth, async (user) => {\r\n      if (!user) {\r\n        window.location.href = \"#/index.html\";\r\n        return;\r\n      }\r\n      currentUser = user;\r\n      await loadSessionDropdown();\r\n      loadSubjects();\r\n      updateStats();\r\n    });\r\n\r\n    // ── SESSION MANAGEMENT ─────────────────────────────────────────────\r\n    async function loadSessionDropdown() {\r\n      const sel = document.getElementById(\"sessionSelector\");\r\n      if (!sel || !currentUser) return;\r\n      sel.innerHTML = '<option value=\"\">Loading sessions…</option>';\r\n      try {\r\n        const snap = await getDocs(collection(db, \"schools\", currentUser.uid, \"sessions\"));\r\n        let activeId = null;\r\n        try {\r\n          const activeSnap = await getDoc(doc(db, \"schools\", currentUser.uid, \"settings\", \"activeSession\"));\r\n          if (activeSnap.exists()) activeId = activeSnap.data().sessionId;\r\n        } catch(e) {}\r\n        let viewSessionId = \"\";\r\n        try { viewSessionId = localStorage.getItem(\"schoolix.viewSessionId\") || \"\"; } catch (_) {}\r\n\r\n        sel.innerHTML = '<option value=\"\">— Select Session —</option>';\r\n        let activeSession = null;\r\n        let sessions = [];\r\n        snap.forEach(d => {\r\n          sessions.push({ id: d.id, ...d.data() });\r\n        });\r\n        sessions.sort((a, b) => (b.startYear || 0) - (a.startYear || 0));\r\n        sessions.forEach(data => {\r\n          const isViewing = data.id === (viewSessionId || activeId);\r\n          const opt = document.createElement(\"option\");\r\n          opt.value = data.session;\r\n          opt.dataset.id = data.id;\r\n          opt.dataset.locked = data.locked ? \"1\" : \"0\";\r\n          opt.textContent = data.session + (isViewing ? \" (Viewing)\" : \"\") + (data.id === activeId ? \" (Active)\" : \"\") + (data.locked ? \" (Locked)\" : \"\");\r\n          if (isViewing) { opt.selected = true; activeSession = data; }\r\n          sel.appendChild(opt);\r\n        });\r\n        if (snap.empty) {\r\n          sel.innerHTML = '<option value=\"\">No sessions — go to Additional Settings</option>';\r\n        }\r\n        if (activeSession) {\r\n          currentSession = activeSession.session;\r\n          currentSessionId = activeSession.id;\r\n          currentSessionLocked = activeSession.locked;\r\n          updateSessionBanner();\r\n        }\r\n      } catch(e) {\r\n        console.error(\"Session load:\", e);\r\n      }\r\n    }\r\n\r\n    window.onSessionChange = function() {\r\n      const sel = document.getElementById(\"sessionSelector\");\r\n      const opt = sel.options[sel.selectedIndex];\r\n      currentSession = sel.value;\r\n      currentSessionId = opt?.dataset?.id || \"\";\r\n      currentSessionLocked = opt && opt.dataset.locked === \"1\";\r\n      updateSessionBanner();\r\n      // Reset report when session changes\r\n      currentStudent = null;\r\n      lastGeneratedReportData = null;\r\n      reportGenerated = false;\r\n      currentReportCardId = null;\r\n      document.getElementById(\"reportSection\").innerHTML = \"\";\r\n      document.getElementById(\"name\").value = \"\";\r\n      document.getElementById(\"class\").value = \"\";\r\n      document.getElementById(\"studentId\").value = \"\";\r\n      updateSaveReportButton();\r\n      // Reset subject marks to 0 for new session\r\n      document.querySelectorAll(\".subject-row input[type=number]\").forEach(inp => { if(inp.placeholder===\"Obtained\") inp.value = 0; });\r\n    };\r\n\r\n    function updateSessionBanner() {\r\n      const lockBanner = document.getElementById(\"sessionLockBanner\");\r\n      const activeBanner = document.getElementById(\"sessionActiveBanner\");\r\n      if (!lockBanner || !activeBanner) return;\r\n      if (!currentSession) { lockBanner.style.display=\"none\"; activeBanner.style.display=\"none\"; return; }\r\n      if (currentSessionLocked) {\r\n        lockBanner.style.display=\"flex\"; activeBanner.style.display=\"none\";\r\n        setSubjectInputsReadOnly(true);\r\n      } else {\r\n        lockBanner.style.display=\"none\"; activeBanner.style.display=\"flex\";\r\n        setSubjectInputsReadOnly(false);\r\n      }\r\n      updateSaveReportButton();\r\n    }\r\n\r\n    function setSubjectInputsReadOnly(readonly) {\r\n      document.querySelectorAll(\".subject-row input\").forEach(inp => {\r\n        inp.readOnly = readonly;\r\n        inp.style.background = readonly ? \"#f8f9fa\" : \"\";\r\n        inp.style.cursor = readonly ? \"not-allowed\" : \"\";\r\n      });\r\n      const addBtn = document.querySelector('button[onclick=\"addSubject()\"]');\r\n      const saveBtn = document.getElementById(\"saveSubjectsBtn\");\r\n      const delBtn = document.getElementById(\"deleteSubjectsBtn\");\r\n      if (addBtn) addBtn.disabled = readonly;\r\n      if (saveBtn) saveBtn.disabled = readonly;\r\n      if (delBtn) delBtn.disabled = readonly;\r\n    }\r\n\r\n    window.viewGeneratedReports = () => {\r\n      window.open(`#/reports.html?uid=${currentUser.uid}`, '_blank');\r\n    };\r\n\r\n    window.deleteAllGlobalSubjects = async () => {\r\n      if (currentSessionLocked) return showStatus('subjectsStatus', \"Selected session is locked. Subjects are view only.\", 'error');\r\n      if (!currentUser) return showStatus('subjectsStatus', \"Please login first.\", 'error');\r\n\r\n      if (!confirm('Delete all global subjects?\\nThis will remove subjects for all students.')) {\r\n        return;\r\n      }\r\n\r\n      const deleteBtn = document.getElementById('deleteSubjectsBtn');\r\n      deleteBtn.disabled = true;\r\n\r\n      try {\r\n        const snapshot = await getDocs(collection(db, \"schools\", currentUser.uid, \"globalSubjects\"));\r\n        const deletePromises = snapshot.docs.map(d => deleteDoc(doc(db, \"schools\", currentUser.uid, \"globalSubjects\", d.id)));\r\n        await Promise.all(deletePromises);\r\n\r\n        // Clear UI\r\n        document.getElementById(\"subjects\").innerHTML = \"\";\r\n        subjectsData = [];\r\n        subjectsSaved = false;\r\n\r\n        updateCardStatus();\r\n        updateStats();\r\n\r\n        showStatus('subjectsStatus', 'All global subjects deleted successfully.', 'success');\r\n\r\n      } catch (error) {\r\n        console.error(\"Delete error:\", error);\r\n        showStatus('subjectsStatus', \"Failed to delete subjects.\", 'error');\r\n      } finally {\r\n        deleteBtn.disabled = false;\r\n      }\r\n    };\r\n\r\n    window.saveSubjects = async () => {\r\n      if (currentSessionLocked) return showStatus('subjectsStatus', \"Selected session is locked. Subjects are view only.\", 'error');\r\n      if (!currentUser) return showStatus('subjectsStatus', \"Please login first.\", 'error');\r\n\r\n      const saveBtn = document.getElementById('saveSubjectsBtn');\r\n      saveBtn.disabled = true;\r\n\r\n      try {\r\n        // Get all valid subjects\r\n        const rows = document.querySelectorAll(\".subject-row\");\r\n        const validSubjects = [];\r\n\r\n        rows.forEach(r => {\r\n          const name = r.children[0]?.value?.trim();\r\n          const obtained = parseFloat(r.children[1]?.value) || 0;\r\n          const maxMarks = parseFloat(r.children[2]?.value) || 100;\r\n\r\n          if (name) {\r\n            validSubjects.push({\r\n              name,\r\n              obtained,\r\n              maxMarks,\r\n              timestamp: serverTimestamp(),\r\n              userId: currentUser.uid,\r\n              isGlobal: true });\r\n          }\r\n        });\r\n\r\n        if (validSubjects.length === 0) {\r\n          saveBtn.disabled = false;\r\n          return showStatus('subjectsStatus', \"No valid subjects to save.\", 'error');\r\n        }\r\n\r\n        // Delete old global subjects first\r\n        const oldSnapshot = await getDocs(collection(db, \"schools\", currentUser.uid, \"globalSubjects\"));\r\n        const deletePromises = oldSnapshot.docs.map(d => deleteDoc(doc(db, \"schools\", currentUser.uid, \"globalSubjects\", d.id)));\r\n        await Promise.all(deletePromises);\r\n\r\n        // Save new global subjects\r\n        const savePromises = validSubjects.map(subject =>\r\n          addDoc(collection(db, \"schools\", currentUser.uid, \"globalSubjects\"), subject)\r\n        );\r\n\r\n        await Promise.all(savePromises);\r\n\r\n        subjectsSaved = true;\r\n        updateCardStatus();\r\n\r\n        showStatus('subjectsStatus', `${validSubjects.length} global subjects saved.`, 'success');\r\n        updateStats();\r\n\r\n      } catch (error) {\r\n        console.error(\"Save global subjects error:\", error);\r\n        showStatus('subjectsStatus', \"Failed to save global subjects.\", 'error');\r\n      } finally {\r\n        saveBtn.disabled = false;\r\n      }\r\n    };\r\n\r\n    function subjectRowHTML(name = \"\", obtained = \"\", maxMarks = 100) {\r\n      const safe = (v) => String(v).replace(/\"/g, \"&quot;\");\r\n      return `\r\n        <input type=\"text\" placeholder=\"Subject Name\" value=\"${safe(name)}\" oninput=\"updateSubjectData(this)\" />\r\n        <input type=\"number\" placeholder=\"Obtained\" value=\"${obtained === \"\" ? \"\" : safe(obtained)}\" oninput=\"updateSubjectData(this); updateStats()\" />\r\n        <input type=\"number\" placeholder=\"Max Marks\" value=\"${safe(maxMarks)}\" oninput=\"updateSubjectData(this); updateStats()\" />\r\n        <button class=\"row-del\" onclick=\"deleteSubject(this)\" title=\"Remove\">\r\n          <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"3 6 5 6 21 6\"/><path d=\"M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2\"/></svg>\r\n        </button>`;\r\n    }\r\n\r\n    window.loadSubjects = async () => {\r\n      if (!currentUser) return showStatus('subjectsStatus', \"Please login first.\", 'error');\r\n\r\n      const container = document.getElementById(\"subjects\");\r\n      container.innerHTML = '<div class=\"loading\"><span class=\"spinner\"></span> Loading global subjects...</div>';\r\n\r\n      try {\r\n        if (unsubscribeSubjects) {\r\n          unsubscribeSubjects();\r\n          unsubscribeSubjects = null;\r\n        }\r\n\r\n        const snapshot = await getDocs(\r\n          query(collection(db, \"schools\", currentUser.uid, \"globalSubjects\"), orderBy('timestamp', 'desc'))\r\n        );\r\n\r\n        container.innerHTML = \"\";\r\n        subjectsData = [];\r\n\r\n        if (snapshot.empty) {\r\n          container.innerHTML = `<div class=\"state-box\">\r\n            <div class=\"icon-circle\"><svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"/><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"/></svg></div>\r\n            <h4>No global subjects saved</h4>\r\n            <p>Add and save subjects to continue.</p>\r\n          </div>`;\r\n          subjectsSaved = false;\r\n          updateCardStatus();\r\n          updateStats();\r\n          setSubjectInputsReadOnly(currentSessionLocked);\r\n          return;\r\n        }\r\n\r\n        let index = 0;\r\n        snapshot.forEach((docSnap) => {\r\n          const subject = docSnap.data();\r\n          subjectsData[index] = subject;\r\n\r\n          const div = document.createElement(\"div\");\r\n          div.className = \"subject-row\";\r\n          div.innerHTML = subjectRowHTML(subject.name ?? \"\", subject.obtained ?? 0, subject.maxMarks ?? 100);\r\n          container.appendChild(div);\r\n          index++;\r\n        });\r\n\r\n        subjectsSaved = true;\r\n        updateCardStatus();\r\n        updateStats();\r\n        setSubjectInputsReadOnly(currentSessionLocked);\r\n        showStatus('subjectsStatus', `Loaded ${snapshot.size} global subjects.`, 'success');\r\n\r\n      } catch (error) {\r\n        console.error(\"Load global error:\", error);\r\n        document.getElementById(\"subjects\").innerHTML = `<div class=\"state-box\">\r\n          <div class=\"icon-circle\" style=\"background:#fef2f2;color:#dc2626\"><svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"8\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"16\" x2=\"12.01\" y2=\"16\"/></svg></div>\r\n          <h4>Error loading global subjects</h4>\r\n          <p>Try saving first.</p>\r\n        </div>`;\r\n        showStatus('subjectsStatus', \"Error loading global subjects.\", 'error');\r\n      }\r\n    };\r\n\r\n    window.updateStats = () => {\r\n      const rows = document.querySelectorAll(\".subject-row\");\r\n      let count = 0, totalObtained = 0, totalMax = 0;\r\n\r\n      rows.forEach(r => {\r\n        const name = r.children[0]?.value?.trim();\r\n        const obtained = parseFloat(r.children[1]?.value) || 0;\r\n        const maxMarks = parseFloat(r.children[2]?.value) || 100;\r\n\r\n        if (name) {\r\n          count++;\r\n          totalObtained += obtained;\r\n          totalMax += maxMarks;\r\n        }\r\n      });\r\n\r\n      const avg = totalMax > 0 ? ((totalObtained / totalMax) * 100).toFixed(1) : 0;\r\n\r\n      document.getElementById(\"subjectCount\").textContent = `${count} Subjects`;\r\n      document.getElementById(\"totalMarks\").textContent = `${totalObtained}/${totalMax}`;\r\n      document.getElementById(\"avgMarks\").textContent = `${avg}%`;\r\n    };\r\n\r\n    window.addSubject = () => {\r\n      if (currentSessionLocked) return showStatus('subjectsStatus', \"Selected session is locked. Subjects are view only.\", 'error');\r\n      const div = document.createElement(\"div\");\r\n      div.className = \"subject-row\";\r\n      div.innerHTML = subjectRowHTML(\"\", \"\", 100);\r\n      document.getElementById(\"subjects\").appendChild(div);\r\n      subjectsSaved = false;\r\n      updateCardStatus();\r\n      updateStats();\r\n    };\r\n\r\n    window.deleteSubject = (btn) => {\r\n      if (currentSessionLocked) return showStatus('subjectsStatus', \"Selected session is locked. Subjects are view only.\", 'error');\r\n      btn.parentElement.remove();\r\n      subjectsSaved = false;\r\n      updateCardStatus();\r\n      updateStats();\r\n    };\r\n\r\n    window.updateSubjectData = (input) => {\r\n      const row = input.closest('.subject-row');\r\n      const index = Array.from(row.parentNode.children).indexOf(row);\r\n\r\n      if (index >= subjectsData.length) {\r\n        subjectsData[index] = { name: '', obtained: 0, maxMarks: 100 };\r\n      }\r\n\r\n      if (input === row.children[0]) subjectsData[index].name = input.value;\r\n      if (input === row.children[1]) subjectsData[index].obtained = parseFloat(input.value) || 0;\r\n      if (input === row.children[2]) subjectsData[index].maxMarks = parseFloat(input.value) || 100;\r\n\r\n      subjectsSaved = false;\r\n      updateCardStatus();\r\n    };\r\n\r\n    window.fetchStudent = async () => {\r\n      const studentId = document.getElementById(\"studentId\").value.trim();\r\n      if (!studentId || !currentUser) return alert(\"Enter student ID and login first.\");\r\n\r\n      try {\r\n        document.getElementById(\"reportSection\").innerHTML = '<div class=\"panel\"><div class=\"loading\"><span class=\"spinner\"></span> Fetching student...</div></div>';\r\n\r\n        const q = query(collection(db, \"schools\", currentUser.uid, \"students\"), where(\"studentId\", \"==\", studentId));\r\n        const snap = await getDocs(q);\r\n\r\n        if (snap.empty) {\r\n          alert(\"Student not found. Add student first.\");\r\n          document.getElementById(\"reportSection\").innerHTML = \"\";\r\n          return;\r\n        }\r\n\r\n        snap.forEach(docSnap => {\r\n          currentStudent = docSnap.data();\r\n        });\r\n\r\n        document.getElementById(\"name\").value = currentStudent.name || \"N/A\";\r\n        document.getElementById(\"class\").value = `${currentStudent.class || \"\"}-${currentStudent.section || \"\"}`.replace(/--/g, \"-\");\r\n        document.getElementById(\"reportSection\").innerHTML = \"\";\r\n\r\n        alert(\"Student fetched successfully.\");\r\n\r\n      } catch (error) {\r\n        console.error(\"Fetch error:\", error);\r\n        alert(\"Error fetching student.\");\r\n      }\r\n    };\r\n\r\n    window.generateReport = () => {\r\n      if (currentSessionLocked) return alert(\"Selected session is locked. Report cards are view only.\");\r\n      if (!currentStudent) return alert(\"Fetch student first.\");\r\n\r\n      const rows = document.querySelectorAll(\".subject-row\");\r\n      let htmlRows = \"\", totalObtained = 0, totalMax = 0;\r\n\r\n      rows.forEach(r => {\r\n        const name = r.children[0]?.value?.trim();\r\n        const obtained = parseFloat(r.children[1]?.value) || 0;\r\n        const maxMarks = parseFloat(r.children[2]?.value) || 100;\r\n\r\n        if (name) {\r\n          totalObtained += obtained;\r\n          totalMax += maxMarks;\r\n          const percent = maxMarks > 0 ? ((obtained / maxMarks) * 100) : 0;\r\n          const remarks = percent >= 90 ? \"Excellent\" : percent >= 75 ? \"Good\" : percent >= 60 ? \"Satisfactory\" : \"Needs Improvement\";\r\n          htmlRows += `<tr><td>${name}</td><td>${obtained}</td><td>${maxMarks}</td><td>${percent.toFixed(1)}%</td><td>${remarks}</td></tr>`;\r\n        }\r\n      });\r\n\r\n      if (!htmlRows) return alert(\"Add global subjects with marks first.\");\r\n\r\n      const percentage = ((totalObtained / totalMax) * 100).toFixed(2);\r\n      const grade = percentage >= 90 ? \"A+\" : percentage >= 80 ? \"A\" : percentage >= 70 ? \"B+\" :\r\n                    percentage >= 60 ? \"B\" : percentage >= 50 ? \"C\" : percentage >= 40 ? \"D\" : \"F\";\r\n\r\n      reportGenerated = true;\r\n      updateSaveReportButton();\r\n\r\n      const academicYear = currentSession || `${new Date().getFullYear()}-${new Date().getFullYear()+1}`;\r\n      const schoolName = window.SchoolBranding?.getSchoolName() || \"Schoolix Public School\";\r\n      lastGeneratedReportData = {\r\n        totalObtained,\r\n        totalMax,\r\n        percentage: Number(percentage),\r\n        grade,\r\n        subjects: Array.from(rows).map((r) => ({\r\n          name: r.children[0]?.value?.trim(),\r\n          obtained: parseFloat(r.children[1]?.value) || 0,\r\n          maxMarks: parseFloat(r.children[2]?.value) || 100\r\n        })).filter((s) => s.name)\r\n      };\r\n\r\n      document.getElementById(\"reportSection\").innerHTML = `\r\n        <div class=\"report\">\r\n          <div class=\"r-head\">\r\n            <div class=\"r-brand\">Academic Report Card</div>\r\n            <h2>${schoolName}</h2>\r\n            <div class=\"r-sub\">Report Card</div>\r\n            <div class=\"r-year\">Academic Year: ${academicYear}</div>\r\n          </div>\r\n\r\n          <div class=\"r-meta\">\r\n            <div><strong>Name:</strong> <span>${currentStudent.name || \"N/A\"}</span></div>\r\n            <div><strong>Student ID:</strong> <span>${currentStudent.studentId || \"N/A\"}</span></div>\r\n            <div><strong>Class:</strong> <span>${currentStudent.class || \"N/A\"}-${currentStudent.section || \"\"}</span></div>\r\n            <div><strong>Roll No:</strong> <span>${currentStudent.roll || \"N/A\"}</span></div>\r\n          </div>\r\n\r\n          <table>\r\n            <thead>\r\n              <tr><th>Subject</th><th>Obtained</th><th>Maximum</th><th>Percentage</th><th>Remarks</th></tr>\r\n            </thead>\r\n            <tbody>${htmlRows}</tbody>\r\n          </table>\r\n\r\n          <div class=\"r-stats\">\r\n            <div class=\"r-stat\"><b>${totalObtained.toFixed(0)}</b><small>Total Obtained</small></div>\r\n            <div class=\"r-stat\"><b>${totalMax}</b><small>Total Maximum</small></div>\r\n            <div class=\"r-stat\"><b>${percentage}%</b><small>Percentage</small></div>\r\n            <div class=\"r-stat\"><b>${grade}</b><small>Final Grade</small></div>\r\n          </div>\r\n\r\n          <div class=\"r-sign\">\r\n            <div>Class Teacher Signature</div>\r\n            <div>Parent/Guardian Signature</div>\r\n            <div>Principal Signature</div>\r\n          </div>\r\n\r\n          <div class=\"r-foot\">\r\n            Generated on: ${new Date().toLocaleDateString()} &nbsp;|&nbsp; Prepared by: ${currentUser.email}\r\n          </div>\r\n        </div>\r\n      `;\r\n    };\r\n\r\n    window.saveReportCard = async () => {\r\n      if (currentSessionLocked) return alert(\"Selected session is locked. Report cards are view only.\");\r\n      if (!reportGenerated || !document.querySelector(\".report\")) {\r\n        return alert(\"Generate report first.\");\r\n      }\r\n\r\n      if (!currentStudent || !lastGeneratedReportData) return alert(\"Fetch student first.\");\r\n\r\n      const saveBtn = document.getElementById('saveReportBtn');\r\n      saveBtn.disabled = true;\r\n\r\n      try {\r\n        const reportHtml = document.querySelector(\".report\").outerHTML;\r\n\r\n        const reportData = {\r\n          student: currentStudent,\r\n          subjects: lastGeneratedReportData.subjects.map((s) => ({ ...s, isGlobal: true })),\r\n          totalObtained: lastGeneratedReportData.totalObtained,\r\n          totalMax: lastGeneratedReportData.totalMax,\r\n          percentage: lastGeneratedReportData.percentage,\r\n          grade: lastGeneratedReportData.grade,\r\n          reportHtml,\r\n          createdAt: serverTimestamp(),\r\n          createdBy: currentUser.uid,\r\n          studentId: currentStudent.studentId,\r\n          usedGlobalSubjects: true,\r\n          sessionId: currentSessionId || \"\",\r\n          session: currentSession || \"N/A\",\r\n          locked: false\r\n        };\r\n\r\n        const docRef = await addDoc(collection(db, \"schools\", currentUser.uid, \"reportCards\"), reportData);\r\n        currentReportCardId = docRef.id;\r\n\r\n        alert(\"Report card saved successfully. Check View All Reports.\");\r\n        document.getElementById(\"lockReportBtn\").disabled = false;\r\n\r\n      } catch (error) {\r\n        console.error(\"Save report error:\", error);\r\n        alert(\"Failed to save report card.\");\r\n      } finally {\r\n        setTimeout(() => {\r\n          updateSaveReportButton();\r\n        }, 2000);\r\n      }\r\n    };\r\n\r\n    window.lockReportCard = async () => {\r\n      if (currentSessionLocked) return alert(\"Selected session is locked. Report cards are already view only.\");\r\n      if (!currentReportCardId) return alert(\"Save the report card first.\");\r\n      if (!confirm(\"Lock this report card? Marks cannot be changed after locking.\")) return;\r\n      try {\r\n        await updateDoc(doc(db, \"schools\", currentUser.uid, \"reportCards\", currentReportCardId), { locked: true });\r\n        alert(\"Report card locked successfully.\");\r\n        const lockBtn = document.getElementById(\"lockReportBtn\");\r\n        lockBtn.disabled = true;\r\n        lockBtn.textContent = \"Locked\";\r\n        // disable editing\r\n        document.querySelectorAll(\".subject-row input[type=number]\").forEach(inp => {\r\n          inp.readOnly = true; inp.style.background=\"#f8f9fa\"; inp.style.cursor=\"not-allowed\";\r\n        });\r\n        document.getElementById(\"saveReportBtn\").disabled = true;\r\n      } catch(e) {\r\n        console.error(\"Lock failed:\", e);\r\n        alert(\"Failed to lock report card.\");\r\n      }\r\n    };\r\n\r\n    window.printReport = () => {\r\n      const report = document.querySelector(\".report\");\r\n      if (!report) return alert(\"Generate report first.\");\r\n\r\n      const printWin = window.open('', '_blank');\r\n      printWin.document.write(`\r\n        <html><head>\r\n<title>Report Card</title>\r\n        <style>\r\n          body{font-family:'Inter',Arial,sans-serif;margin:24px;color:#0f172a;}\r\n          .report{border:1px solid #d1d5db;border-radius:12px;padding:36px;}\r\n          .r-head{text-align:center;border-bottom:2px solid #000;padding-bottom:14px;margin-bottom:20px;}\r\n          .r-brand{text-transform:uppercase;letter-spacing:.16em;color:#1d4ed8;font-weight:700;font-size:11px;}\r\n          .r-head h2{font-size:1.8rem;margin:4px 0;}\r\n          .r-sub{color:#64748b;font-weight:600;}\r\n          .r-year{color:#94a3b8;font-size:12px;}\r\n          .r-meta{display:grid;grid-template-columns:1fr 1fr;gap:8px 24px;margin-bottom:18px;}\r\n          .r-meta div{padding:8px 10px;background:#f8fafc;border:1px solid #e5e7eb;border-radius:8px;font-size:13px;}\r\n          table{width:100%;border-collapse:collapse;margin:6px 0 18px;}\r\n          th,td{border:1px solid #d1d5db;padding:9px 10px;text-align:center;font-size:13px;}\r\n          td:first-child{text-align:left;}\r\n          th{background:#1d4ed8;color:#fff;}\r\n          .r-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:22px;}\r\n          .r-stat{border:1px solid #e5e7eb;border-radius:10px;padding:12px;text-align:center;background:#f8fafc;}\r\n          .r-stat b{display:block;font-size:1.4rem;color:#1d4ed8;}\r\n          .r-stat small{color:#64748b;font-size:11px;text-transform:uppercase;}\r\n          .r-sign{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin-top:44px;}\r\n          .r-sign div{text-align:center;border-top:1.5px solid #000;padding-top:8px;font-size:12px;}\r\n          .r-foot{margin-top:24px;padding-top:12px;border-top:1px dashed #d1d5db;text-align:center;color:#94a3b8;font-size:11px;}\r\n          @media print{body{margin:0;}.report{box-shadow:none;border:none;}}\r\n        </style>\r\n</head><body>${report.outerHTML}","styles":[{"tag":"style","attributes":{"id":"sxCriticalLoaderStyle"},"text":"\r\nhtml.sx-page-loading,\r\nhtml.sx-page-loading body {\r\n  min-height: 100%;\r\n  background: #f8fafc !important;\r\n}\r\nhtml.sx-page-loading body::before,\r\nhtml.sx-page-loading body::after {\r\n  visibility: hidden !important;\r\n}\r\nhtml.sx-page-loading body > :not(#sxPageLoader):not(script):not(style) {\r\n  visibility: hidden !important;\r\n}\r\n.sx-page-loader {\r\n  position: fixed;\r\n  inset: 0;\r\n  z-index: 2147482500;\r\n  display: flex;\r\n  align-items: stretch;\r\n  justify-content: stretch;\r\n  background: #f8fafc;\r\n  transition: opacity 0.25s cubic-bezier(0.4, 0, 0.2, 1), visibility 0.25s ease;\r\n  overflow: hidden;\r\n}\r\n.sx-page-loader.is-hidden {\r\n  opacity: 0;\r\n  visibility: hidden;\r\n  pointer-events: none;\r\n}\r\n.sx-page-loader .dots-container {\r\n  position: fixed;\r\n  inset: 0;\r\n  display: block;\r\n  width: 100vw;\r\n  height: 100vh;\r\n  padding: 0;\r\n  margin: 0;\r\n  overflow: hidden;\r\n  background: #f8fafc;\r\n}\r\n.sx-page-loader .dots-container::before,\r\n.sx-page-loader .dots-container::after,\r\n.sx-page-loader .dot {\r\n  display: none !important;\r\n}\r\n"},{"tag":"link","attributes":{"rel":"stylesheet","href":"schoolix-polish.css"},"text":""},{"tag":"link","attributes":{"rel":"stylesheet","href":"admin-shell.css?v=navbar-20260721"},"text":""}],"scripts":[{"attributes":{"id":"sxCriticalLoaderScript"},"text":"\r\n(function () {\r\n  var root = document.documentElement;\r\n  root.classList.add(\"sx-page-loading\");\r\n  window.SchoolixPageLoaderEarly = window.SchoolixPageLoaderEarly || { startedAt: Date.now() };\r\n\r\n  function markEarlyReady(reason) {\r\n    window.SchoolixPageLoaderEarly.ready = true;\r\n    window.SchoolixPageLoaderEarly.reason = reason || \"dom-ready\";\r\n    try {\r\n      window.dispatchEvent(new CustomEvent(\"schoolix:critical-load-ready\", { detail: window.SchoolixPageLoaderEarly }));\r\n    } catch (_) {}\r\n  }\r\n\r\n  function afterFirstPaint(reason) {\r\n    requestAnimationFrame(function () {\r\n      requestAnimationFrame(function () { markEarlyReady(reason); });\r\n    });\r\n  }\r\n\r\n  function emergencyHide() {\r\n    if (window.SchoolixPageLoader || !root.classList.contains(\"sx-page-loading\")) return;\r\n    root.classList.remove(\"sx-page-loading\");\r\n    root.classList.add(\"sx-page-loaded\");\r\n    var loader = document.getElementById(\"sxPageLoader\");\r\n    if (!loader) return;\r\n    loader.classList.add(\"is-hidden\");\r\n    setTimeout(function () { loader.remove(); }, 260);\r\n  }\r\n\r\n  if (document.readyState === \"loading\") {\r\n    document.addEventListener(\"DOMContentLoaded\", function () { afterFirstPaint(\"dom-ready\"); }, { once: true });\r\n  } else {\r\n    afterFirstPaint(document.readyState === \"complete\" ? \"document-complete\" : \"dom-ready\");\r\n  }\r\n  window.addEventListener(\"load\", function () { markEarlyReady(\"window-load\"); }, { once: true });\r\n  setTimeout(emergencyHide, 3200);\r\n}());\r\n"},{"attributes":{"type":"module"},"text":"\r\n    import { initializeApp } from \"./firebase-compat.js\";\r\n    import { getFirestore, collection, getDocs, getDoc, doc, addDoc, updateDoc, deleteDoc, query, where, orderBy, serverTimestamp } from \"./firebase-compat.js\";\r\n    import { getAuth, onAuthStateChanged } from \"./firebase-compat.js\";\r\n\r\n    const firebaseConfig = {\r\n       apiKey: \"AIzaSyAomGwef93HFT9Xyx7SVW95FPw_IcIAICE\",\r\n      authDomain: \"schoolix-48107.firebaseapp.com\",\r\n      projectId: \"schoolix-48107\",\r\n      storageBucket: \"schoolix-48107.firebasestorage.app\",\r\n      messagingSenderId: \"133937954491\",\r\n      appId: \"1:133937954491:web:69d8064422617eb8c4339e\",\r\n      measurementId: \"G-EG23XE5Q0Z\"\r\n    };\r\n\r\n    const app = initializeApp(firebaseConfig);\r\n    const db = getFirestore(app);\r\n    const auth = getAuth(app);\r\n\r\n    let currentUser = null;\r\n    let currentStudent = null;\r\n    let unsubscribeSubjects = null;\r\n    let subjectsData = [];\r\n    let subjectsSaved = false;\r\n    let reportGenerated = false;\r\n    let lastGeneratedReportData = null;\r\n    let currentSession = \"\";\r\n    let currentSessionId = \"\";\r\n    let currentSessionLocked = false;\r\n    let currentReportCardId = null;\r\n\r\n    onAuthStateChanged(auth, async (user) => {\r\n      if (!user) {\r\n        window.location.href = \"#/index.html\";\r\n        return;\r\n      }\r\n      currentUser = user;\r\n      await loadSessionDropdown();\r\n      loadSubjects();\r\n      updateStats();\r\n    });\r\n\r\n    // ── SESSION MANAGEMENT ─────────────────────────────────────────────\r\n    async function loadSessionDropdown() {\r\n      const sel = document.getElementById(\"sessionSelector\");\r\n      if (!sel || !currentUser) return;\r\n      sel.innerHTML = '<option value=\"\">Loading sessions…</option>';\r\n      try {\r\n        const snap = await getDocs(collection(db, \"schools\", currentUser.uid, \"sessions\"));\r\n        let activeId = null;\r\n        try {\r\n          const activeSnap = await getDoc(doc(db, \"schools\", currentUser.uid, \"settings\", \"activeSession\"));\r\n          if (activeSnap.exists()) activeId = activeSnap.data().sessionId;\r\n        } catch(e) {}\r\n        let viewSessionId = \"\";\r\n        try { viewSessionId = localStorage.getItem(\"schoolix.viewSessionId\") || \"\"; } catch (_) {}\r\n\r\n        sel.innerHTML = '<option value=\"\">— Select Session —</option>';\r\n        let activeSession = null;\r\n        let sessions = [];\r\n        snap.forEach(d => {\r\n          sessions.push({ id: d.id, ...d.data() });\r\n        });\r\n        sessions.sort((a, b) => (b.startYear || 0) - (a.startYear || 0));\r\n        sessions.forEach(data => {\r\n          const isViewing = data.id === (viewSessionId || activeId);\r\n          const opt = document.createElement(\"option\");\r\n          opt.value = data.session;\r\n          opt.dataset.id = data.id;\r\n          opt.dataset.locked = data.locked ? \"1\" : \"0\";\r\n          opt.textContent = data.session + (isViewing ? \" (Viewing)\" : \"\") + (data.id === activeId ? \" (Active)\" : \"\") + (data.locked ? \" (Locked)\" : \"\");\r\n          if (isViewing) { opt.selected = true; activeSession = data; }\r\n          sel.appendChild(opt);\r\n        });\r\n        if (snap.empty) {\r\n          sel.innerHTML = '<option value=\"\">No sessions — go to Additional Settings</option>';\r\n        }\r\n        if (activeSession) {\r\n          currentSession = activeSession.session;\r\n          currentSessionId = activeSession.id;\r\n          currentSessionLocked = activeSession.locked;\r\n          updateSessionBanner();\r\n        }\r\n      } catch(e) {\r\n        console.error(\"Session load:\", e);\r\n      }\r\n    }\r\n\r\n    window.onSessionChange = function() {\r\n      const sel = document.getElementById(\"sessionSelector\");\r\n      const opt = sel.options[sel.selectedIndex];\r\n      currentSession = sel.value;\r\n      currentSessionId = opt?.dataset?.id || \"\";\r\n      currentSessionLocked = opt && opt.dataset.locked === \"1\";\r\n      updateSessionBanner();\r\n      // Reset report when session changes\r\n      currentStudent = null;\r\n      lastGeneratedReportData = null;\r\n      reportGenerated = false;\r\n      currentReportCardId = null;\r\n      document.getElementById(\"reportSection\").innerHTML = \"\";\r\n      document.getElementById(\"name\").value = \"\";\r\n      document.getElementById(\"class\").value = \"\";\r\n      document.getElementById(\"studentId\").value = \"\";\r\n      updateSaveReportButton();\r\n      // Reset subject marks to 0 for new session\r\n      document.querySelectorAll(\".subject-row input[type=number]\").forEach(inp => { if(inp.placeholder===\"Obtained\") inp.value = 0; });\r\n    };\r\n\r\n    function updateSessionBanner() {\r\n      const lockBanner = document.getElementById(\"sessionLockBanner\");\r\n      const activeBanner = document.getElementById(\"sessionActiveBanner\");\r\n      if (!lockBanner || !activeBanner) return;\r\n      if (!currentSession) { lockBanner.style.display=\"none\"; activeBanner.style.display=\"none\"; return; }\r\n      if (currentSessionLocked) {\r\n        lockBanner.style.display=\"flex\"; activeBanner.style.display=\"none\";\r\n        setSubjectInputsReadOnly(true);\r\n      } else {\r\n        lockBanner.style.display=\"none\"; activeBanner.style.display=\"flex\";\r\n        setSubjectInputsReadOnly(false);\r\n      }\r\n      updateSaveReportButton();\r\n    }\r\n\r\n    function setSubjectInputsReadOnly(readonly) {\r\n      document.querySelectorAll(\".subject-row input\").forEach(inp => {\r\n        inp.readOnly = readonly;\r\n        inp.style.background = readonly ? \"#f8f9fa\" : \"\";\r\n        inp.style.cursor = readonly ? \"not-allowed\" : \"\";\r\n      });\r\n      const addBtn = document.querySelector('button[onclick=\"addSubject()\"]');\r\n      const saveBtn = document.getElementById(\"saveSubjectsBtn\");\r\n      const delBtn = document.getElementById(\"deleteSubjectsBtn\");\r\n      if (addBtn) addBtn.disabled = readonly;\r\n      if (saveBtn) saveBtn.disabled = readonly;\r\n      if (delBtn) delBtn.disabled = readonly;\r\n    }\r\n\r\n    window.viewGeneratedReports = () => {\r\n      window.open(`#/reports.html?uid=${currentUser.uid}`, '_blank');\r\n    };\r\n\r\n    window.deleteAllGlobalSubjects = async () => {\r\n      if (currentSessionLocked) return showStatus('subjectsStatus', \"Selected session is locked. Subjects are view only.\", 'error');\r\n      if (!currentUser) return showStatus('subjectsStatus', \"Please login first.\", 'error');\r\n\r\n      if (!confirm('Delete all global subjects?\\nThis will remove subjects for all students.')) {\r\n        return;\r\n      }\r\n\r\n      const deleteBtn = document.getElementById('deleteSubjectsBtn');\r\n      deleteBtn.disabled = true;\r\n\r\n      try {\r\n        const snapshot = await getDocs(collection(db, \"schools\", currentUser.uid, \"globalSubjects\"));\r\n        const deletePromises = snapshot.docs.map(d => deleteDoc(doc(db, \"schools\", currentUser.uid, \"globalSubjects\", d.id)));\r\n        await Promise.all(deletePromises);\r\n\r\n        // Clear UI\r\n        document.getElementById(\"subjects\").innerHTML = \"\";\r\n        subjectsData = [];\r\n        subjectsSaved = false;\r\n\r\n        updateCardStatus();\r\n        updateStats();\r\n\r\n        showStatus('subjectsStatus', 'All global subjects deleted successfully.', 'success');\r\n\r\n      } catch (error) {\r\n        console.error(\"Delete error:\", error);\r\n        showStatus('subjectsStatus', \"Failed to delete subjects.\", 'error');\r\n      } finally {\r\n        deleteBtn.disabled = false;\r\n      }\r\n    };\r\n\r\n    window.saveSubjects = async () => {\r\n      if (currentSessionLocked) return showStatus('subjectsStatus', \"Selected session is locked. Subjects are view only.\", 'error');\r\n      if (!currentUser) return showStatus('subjectsStatus', \"Please login first.\", 'error');\r\n\r\n      const saveBtn = document.getElementById('saveSubjectsBtn');\r\n      saveBtn.disabled = true;\r\n\r\n      try {\r\n        // Get all valid subjects\r\n        const rows = document.querySelectorAll(\".subject-row\");\r\n        const validSubjects = [];\r\n\r\n        rows.forEach(r => {\r\n          const name = r.children[0]?.value?.trim();\r\n          const obtained = parseFloat(r.children[1]?.value) || 0;\r\n          const maxMarks = parseFloat(r.children[2]?.value) || 100;\r\n\r\n          if (name) {\r\n            validSubjects.push({\r\n              name,\r\n              obtained,\r\n              maxMarks,\r\n              timestamp: serverTimestamp(),\r\n              userId: currentUser.uid,\r\n              isGlobal: true });\r\n          }\r\n        });\r\n\r\n        if (validSubjects.length === 0) {\r\n          saveBtn.disabled = false;\r\n          return showStatus('subjectsStatus', \"No valid subjects to save.\", 'error');\r\n        }\r\n\r\n        // Delete old global subjects first\r\n        const oldSnapshot = await getDocs(collection(db, \"schools\", currentUser.uid, \"globalSubjects\"));\r\n        const deletePromises = oldSnapshot.docs.map(d => deleteDoc(doc(db, \"schools\", currentUser.uid, \"globalSubjects\", d.id)));\r\n        await Promise.all(deletePromises);\r\n\r\n        // Save new global subjects\r\n        const savePromises = validSubjects.map(subject =>\r\n          addDoc(collection(db, \"schools\", currentUser.uid, \"globalSubjects\"), subject)\r\n        );\r\n\r\n        await Promise.all(savePromises);\r\n\r\n        subjectsSaved = true;\r\n        updateCardStatus();\r\n\r\n        showStatus('subjectsStatus', `${validSubjects.length} global subjects saved.`, 'success');\r\n        updateStats();\r\n\r\n      } catch (error) {\r\n        console.error(\"Save global subjects error:\", error);\r\n        showStatus('subjectsStatus', \"Failed to save global subjects.\", 'error');\r\n      } finally {\r\n        saveBtn.disabled = false;\r\n      }\r\n    };\r\n\r\n    function subjectRowHTML(name = \"\", obtained = \"\", maxMarks = 100) {\r\n      const safe = (v) => String(v).replace(/\"/g, \"&quot;\");\r\n      return `\r\n        <input type=\"text\" placeholder=\"Subject Name\" value=\"${safe(name)}\" oninput=\"updateSubjectData(this)\" />\r\n        <input type=\"number\" placeholder=\"Obtained\" value=\"${obtained === \"\" ? \"\" : safe(obtained)}\" oninput=\"updateSubjectData(this); updateStats()\" />\r\n        <input type=\"number\" placeholder=\"Max Marks\" value=\"${safe(maxMarks)}\" oninput=\"updateSubjectData(this); updateStats()\" />\r\n        <button class=\"row-del\" onclick=\"deleteSubject(this)\" title=\"Remove\">\r\n          <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"3 6 5 6 21 6\"/><path d=\"M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2\"/></svg>\r\n        </button>`;\r\n    }\r\n\r\n    window.loadSubjects = async () => {\r\n      if (!currentUser) return showStatus('subjectsStatus', \"Please login first.\", 'error');\r\n\r\n      const container = document.getElementById(\"subjects\");\r\n      container.innerHTML = '<div class=\"loading\"><span class=\"spinner\"></span> Loading global subjects...</div>';\r\n\r\n      try {\r\n        if (unsubscribeSubjects) {\r\n          unsubscribeSubjects();\r\n          unsubscribeSubjects = null;\r\n        }\r\n\r\n        const snapshot = await getDocs(\r\n          query(collection(db, \"schools\", currentUser.uid, \"globalSubjects\"), orderBy('timestamp', 'desc'))\r\n        );\r\n\r\n        container.innerHTML = \"\";\r\n        subjectsData = [];\r\n\r\n        if (snapshot.empty) {\r\n          container.innerHTML = `<div class=\"state-box\">\r\n            <div class=\"icon-circle\"><svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"/><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"/></svg></div>\r\n            <h4>No global subjects saved</h4>\r\n            <p>Add and save subjects to continue.</p>\r\n          </div>`;\r\n          subjectsSaved = false;\r\n          updateCardStatus();\r\n          updateStats();\r\n          setSubjectInputsReadOnly(currentSessionLocked);\r\n          return;\r\n        }\r\n\r\n        let index = 0;\r\n        snapshot.forEach((docSnap) => {\r\n          const subject = docSnap.data();\r\n          subjectsData[index] = subject;\r\n\r\n          const div = document.createElement(\"div\");\r\n          div.className = \"subject-row\";\r\n          div.innerHTML = subjectRowHTML(subject.name ?? \"\", subject.obtained ?? 0, subject.maxMarks ?? 100);\r\n          container.appendChild(div);\r\n          index++;\r\n        });\r\n\r\n        subjectsSaved = true;\r\n        updateCardStatus();\r\n        updateStats();\r\n        setSubjectInputsReadOnly(currentSessionLocked);\r\n        showStatus('subjectsStatus', `Loaded ${snapshot.size} global subjects.`, 'success');\r\n\r\n      } catch (error) {\r\n        console.error(\"Load global error:\", error);\r\n        document.getElementById(\"subjects\").innerHTML = `<div class=\"state-box\">\r\n          <div class=\"icon-circle\" style=\"background:#fef2f2;color:#dc2626\"><svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"8\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"16\" x2=\"12.01\" y2=\"16\"/></svg></div>\r\n          <h4>Error loading global subjects</h4>\r\n          <p>Try saving first.</p>\r\n        </div>`;\r\n        showStatus('subjectsStatus', \"Error loading global subjects.\", 'error');\r\n      }\r\n    };\r\n\r\n    window.updateStats = () => {\r\n      const rows = document.querySelectorAll(\".subject-row\");\r\n      let count = 0, totalObtained = 0, totalMax = 0;\r\n\r\n      rows.forEach(r => {\r\n        const name = r.children[0]?.value?.trim();\r\n        const obtained = parseFloat(r.children[1]?.value) || 0;\r\n        const maxMarks = parseFloat(r.children[2]?.value) || 100;\r\n\r\n        if (name) {\r\n          count++;\r\n          totalObtained += obtained;\r\n          totalMax += maxMarks;\r\n        }\r\n      });\r\n\r\n      const avg = totalMax > 0 ? ((totalObtained / totalMax) * 100).toFixed(1) : 0;\r\n\r\n      document.getElementById(\"subjectCount\").textContent = `${count} Subjects`;\r\n      document.getElementById(\"totalMarks\").textContent = `${totalObtained}/${totalMax}`;\r\n      document.getElementById(\"avgMarks\").textContent = `${avg}%`;\r\n    };\r\n\r\n    window.addSubject = () => {\r\n      if (currentSessionLocked) return showStatus('subjectsStatus', \"Selected session is locked. Subjects are view only.\", 'error');\r\n      const div = document.createElement(\"div\");\r\n      div.className = \"subject-row\";\r\n      div.innerHTML = subjectRowHTML(\"\", \"\", 100);\r\n      document.getElementById(\"subjects\").appendChild(div);\r\n      subjectsSaved = false;\r\n      updateCardStatus();\r\n      updateStats();\r\n    };\r\n\r\n    window.deleteSubject = (btn) => {\r\n      if (currentSessionLocked) return showStatus('subjectsStatus', \"Selected session is locked. Subjects are view only.\", 'error');\r\n      btn.parentElement.remove();\r\n      subjectsSaved = false;\r\n      updateCardStatus();\r\n      updateStats();\r\n    };\r\n\r\n    window.updateSubjectData = (input) => {\r\n      const row = input.closest('.subject-row');\r\n      const index = Array.from(row.parentNode.children).indexOf(row);\r\n\r\n      if (index >= subjectsData.length) {\r\n        subjectsData[index] = { name: '', obtained: 0, maxMarks: 100 };\r\n      }\r\n\r\n      if (input === row.children[0]) subjectsData[index].name = input.value;\r\n      if (input === row.children[1]) subjectsData[index].obtained = parseFloat(input.value) || 0;\r\n      if (input === row.children[2]) subjectsData[index].maxMarks = parseFloat(input.value) || 100;\r\n\r\n      subjectsSaved = false;\r\n      updateCardStatus();\r\n    };\r\n\r\n    window.fetchStudent = async () => {\r\n      const studentId = document.getElementById(\"studentId\").value.trim();\r\n      if (!studentId || !currentUser) return alert(\"Enter student ID and login first.\");\r\n\r\n      try {\r\n        document.getElementById(\"reportSection\").innerHTML = '<div class=\"panel\"><div class=\"loading\"><span class=\"spinner\"></span> Fetching student...</div></div>';\r\n\r\n        const q = query(collection(db, \"schools\", currentUser.uid, \"students\"), where(\"studentId\", \"==\", studentId));\r\n        const snap = await getDocs(q);\r\n\r\n        if (snap.empty) {\r\n          alert(\"Student not found. Add student first.\");\r\n          document.getElementById(\"reportSection\").innerHTML = \"\";\r\n          return;\r\n        }\r\n\r\n        snap.forEach(docSnap => {\r\n          currentStudent = docSnap.data();\r\n        });\r\n\r\n        document.getElementById(\"name\").value = currentStudent.name || \"N/A\";\r\n        document.getElementById(\"class\").value = `${currentStudent.class || \"\"}-${currentStudent.section || \"\"}`.replace(/--/g, \"-\");\r\n        document.getElementById(\"reportSection\").innerHTML = \"\";\r\n\r\n        alert(\"Student fetched successfully.\");\r\n\r\n      } catch (error) {\r\n        console.error(\"Fetch error:\", error);\r\n        alert(\"Error fetching student.\");\r\n      }\r\n    };\r\n\r\n    window.generateReport = () => {\r\n      if (currentSessionLocked) return alert(\"Selected session is locked. Report cards are view only.\");\r\n      if (!currentStudent) return alert(\"Fetch student first.\");\r\n\r\n      const rows = document.querySelectorAll(\".subject-row\");\r\n      let htmlRows = \"\", totalObtained = 0, totalMax = 0;\r\n\r\n      rows.forEach(r => {\r\n        const name = r.children[0]?.value?.trim();\r\n        const obtained = parseFloat(r.children[1]?.value) || 0;\r\n        const maxMarks = parseFloat(r.children[2]?.value) || 100;\r\n\r\n        if (name) {\r\n          totalObtained += obtained;\r\n          totalMax += maxMarks;\r\n          const percent = maxMarks > 0 ? ((obtained / maxMarks) * 100) : 0;\r\n          const remarks = percent >= 90 ? \"Excellent\" : percent >= 75 ? \"Good\" : percent >= 60 ? \"Satisfactory\" : \"Needs Improvement\";\r\n          htmlRows += `<tr><td>${name}</td><td>${obtained}</td><td>${maxMarks}</td><td>${percent.toFixed(1)}%</td><td>${remarks}</td></tr>`;\r\n        }\r\n      });\r\n\r\n      if (!htmlRows) return alert(\"Add global subjects with marks first.\");\r\n\r\n      const percentage = ((totalObtained / totalMax) * 100).toFixed(2);\r\n      const grade = percentage >= 90 ? \"A+\" : percentage >= 80 ? \"A\" : percentage >= 70 ? \"B+\" :\r\n                    percentage >= 60 ? \"B\" : percentage >= 50 ? \"C\" : percentage >= 40 ? \"D\" : \"F\";\r\n\r\n      reportGenerated = true;\r\n      updateSaveReportButton();\r\n\r\n      const academicYear = currentSession || `${new Date().getFullYear()}-${new Date().getFullYear()+1}`;\r\n      const schoolName = window.SchoolBranding?.getSchoolName() || \"Schoolix Public School\";\r\n      lastGeneratedReportData = {\r\n        totalObtained,\r\n        totalMax,\r\n        percentage: Number(percentage),\r\n        grade,\r\n        subjects: Array.from(rows).map((r) => ({\r\n          name: r.children[0]?.value?.trim(),\r\n          obtained: parseFloat(r.children[1]?.value) || 0,\r\n          maxMarks: parseFloat(r.children[2]?.value) || 100\r\n        })).filter((s) => s.name)\r\n      };\r\n\r\n      document.getElementById(\"reportSection\").innerHTML = `\r\n        <div class=\"report\">\r\n          <div class=\"r-head\">\r\n            <div class=\"r-brand\">Academic Report Card</div>\r\n            <h2>${schoolName}</h2>\r\n            <div class=\"r-sub\">Report Card</div>\r\n            <div class=\"r-year\">Academic Year: ${academicYear}</div>\r\n          </div>\r\n\r\n          <div class=\"r-meta\">\r\n            <div><strong>Name:</strong> <span>${currentStudent.name || \"N/A\"}</span></div>\r\n            <div><strong>Student ID:</strong> <span>${currentStudent.studentId || \"N/A\"}</span></div>\r\n            <div><strong>Class:</strong> <span>${currentStudent.class || \"N/A\"}-${currentStudent.section || \"\"}</span></div>\r\n            <div><strong>Roll No:</strong> <span>${currentStudent.roll || \"N/A\"}</span></div>\r\n          </div>\r\n\r\n          <table>\r\n            <thead>\r\n              <tr><th>Subject</th><th>Obtained</th><th>Maximum</th><th>Percentage</th><th>Remarks</th></tr>\r\n            </thead>\r\n            <tbody>${htmlRows}</tbody>\r\n          </table>\r\n\r\n          <div class=\"r-stats\">\r\n            <div class=\"r-stat\"><b>${totalObtained.toFixed(0)}</b><small>Total Obtained</small></div>\r\n            <div class=\"r-stat\"><b>${totalMax}</b><small>Total Maximum</small></div>\r\n            <div class=\"r-stat\"><b>${percentage}%</b><small>Percentage</small></div>\r\n            <div class=\"r-stat\"><b>${grade}</b><small>Final Grade</small></div>\r\n          </div>\r\n\r\n          <div class=\"r-sign\">\r\n            <div>Class Teacher Signature</div>\r\n            <div>Parent/Guardian Signature</div>\r\n            <div>Principal Signature</div>\r\n          </div>\r\n\r\n          <div class=\"r-foot\">\r\n            Generated on: ${new Date().toLocaleDateString()} &nbsp;|&nbsp; Prepared by: ${currentUser.email}\r\n          </div>\r\n        </div>\r\n      `;\r\n    };\r\n\r\n    window.saveReportCard = async () => {\r\n      if (currentSessionLocked) return alert(\"Selected session is locked. Report cards are view only.\");\r\n      if (!reportGenerated || !document.querySelector(\".report\")) {\r\n        return alert(\"Generate report first.\");\r\n      }\r\n\r\n      if (!currentStudent || !lastGeneratedReportData) return alert(\"Fetch student first.\");\r\n\r\n      const saveBtn = document.getElementById('saveReportBtn');\r\n      saveBtn.disabled = true;\r\n\r\n      try {\r\n        const reportHtml = document.querySelector(\".report\").outerHTML;\r\n\r\n        const reportData = {\r\n          student: currentStudent,\r\n          subjects: lastGeneratedReportData.subjects.map((s) => ({ ...s, isGlobal: true })),\r\n          totalObtained: lastGeneratedReportData.totalObtained,\r\n          totalMax: lastGeneratedReportData.totalMax,\r\n          percentage: lastGeneratedReportData.percentage,\r\n          grade: lastGeneratedReportData.grade,\r\n          reportHtml,\r\n          createdAt: serverTimestamp(),\r\n          createdBy: currentUser.uid,\r\n          studentId: currentStudent.studentId,\r\n          usedGlobalSubjects: true,\r\n          sessionId: currentSessionId || \"\",\r\n          session: currentSession || \"N/A\",\r\n          locked: false\r\n        };\r\n\r\n        const docRef = await addDoc(collection(db, \"schools\", currentUser.uid, \"reportCards\"), reportData);\r\n        currentReportCardId = docRef.id;\r\n\r\n        alert(\"Report card saved successfully. Check View All Reports.\");\r\n        document.getElementById(\"lockReportBtn\").disabled = false;\r\n\r\n      } catch (error) {\r\n        console.error(\"Save report error:\", error);\r\n        alert(\"Failed to save report card.\");\r\n      } finally {\r\n        setTimeout(() => {\r\n          updateSaveReportButton();\r\n        }, 2000);\r\n      }\r\n    };\r\n\r\n    window.lockReportCard = async () => {\r\n      if (currentSessionLocked) return alert(\"Selected session is locked. Report cards are already view only.\");\r\n      if (!currentReportCardId) return alert(\"Save the report card first.\");\r\n      if (!confirm(\"Lock this report card? Marks cannot be changed after locking.\")) return;\r\n      try {\r\n        await updateDoc(doc(db, \"schools\", currentUser.uid, \"reportCards\", currentReportCardId), { locked: true });\r\n        alert(\"Report card locked successfully.\");\r\n        const lockBtn = document.getElementById(\"lockReportBtn\");\r\n        lockBtn.disabled = true;\r\n        lockBtn.textContent = \"Locked\";\r\n        // disable editing\r\n        document.querySelectorAll(\".subject-row input[type=number]\").forEach(inp => {\r\n          inp.readOnly = true; inp.style.background=\"#f8f9fa\"; inp.style.cursor=\"not-allowed\";\r\n        });\r\n        document.getElementById(\"saveReportBtn\").disabled = true;\r\n      } catch(e) {\r\n        console.error(\"Lock failed:\", e);\r\n        alert(\"Failed to lock report card.\");\r\n      }\r\n    };\r\n\r\n    window.printReport = () => {\r\n      const report = document.querySelector(\".report\");\r\n      if (!report) return alert(\"Generate report first.\");\r\n\r\n      const printWin = window.open('', '_blank');\r\n      printWin.document.write(`\r\n        <html><head>\r\n<title>Report Card</title>\r\n        <style>\r\n          body{font-family:'Inter',Arial,sans-serif;margin:24px;color:#0f172a;}\r\n          .report{border:1px solid #d1d5db;border-radius:12px;padding:36px;}\r\n          .r-head{text-align:center;border-bottom:2px solid #000;padding-bottom:14px;margin-bottom:20px;}\r\n          .r-brand{text-transform:uppercase;letter-spacing:.16em;color:#1d4ed8;font-weight:700;font-size:11px;}\r\n          .r-head h2{font-size:1.8rem;margin:4px 0;}\r\n          .r-sub{color:#64748b;font-weight:600;}\r\n          .r-year{color:#94a3b8;font-size:12px;}\r\n          .r-meta{display:grid;grid-template-columns:1fr 1fr;gap:8px 24px;margin-bottom:18px;}\r\n          .r-meta div{padding:8px 10px;background:#f8fafc;border:1px solid #e5e7eb;border-radius:8px;font-size:13px;}\r\n          table{width:100%;border-collapse:collapse;margin:6px 0 18px;}\r\n          th,td{border:1px solid #d1d5db;padding:9px 10px;text-align:center;font-size:13px;}\r\n          td:first-child{text-align:left;}\r\n          th{background:#1d4ed8;color:#fff;}\r\n          .r-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:22px;}\r\n          .r-stat{border:1px solid #e5e7eb;border-radius:10px;padding:12px;text-align:center;background:#f8fafc;}\r\n          .r-stat b{display:block;font-size:1.4rem;color:#1d4ed8;}\r\n          .r-stat small{color:#64748b;font-size:11px;text-transform:uppercase;}\r\n          .r-sign{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin-top:44px;}\r\n          .r-sign div{text-align:center;border-top:1.5px solid #000;padding-top:8px;font-size:12px;}\r\n          .r-foot{margin-top:24px;padding-top:12px;border-top:1px dashed #d1d5db;text-align:center;color:#94a3b8;font-size:11px;}\r\n          @media print{body{margin:0;}.report{box-shadow:none;border:none;}}\r\n        </style>\r\n</head><body>${report.outerHTML}</body></html>\r\n      `);\r\n      printWin.document.close();\r\n      printWin.focus();\r\n      setTimeout(() => printWin.print(), 300);\r\n    };\r\n\r\n    window.clearAll = () => {\r\n      if(confirm(\"Clear everything? Global subjects will remain saved.\")) {\r\n        document.getElementById(\"studentId\").value = \"\";\r\n        document.getElementById(\"name\").value = \"\";\r\n        document.getElementById(\"class\").value = \"\";\r\n        document.getElementById(\"reportSection\").innerHTML = \"\";\r\n        currentStudent = null;\r\n        reportGenerated = false;\r\n        lastGeneratedReportData = null;\r\n        updateSaveReportButton();\r\n      }\r\n    };\r\n\r\n    window.updateCardStatus = () => {\r\n      // status now reflected via stats chips; kept for compatibility\r\n    };\r\n\r\n    window.updateSaveReportButton = () => {\r\n      const saveReportBtn = document.getElementById('saveReportBtn');\r\n      const lockBtn = document.getElementById('lockReportBtn');\r\n      const printBtn = document.querySelector('button[onclick=\"printReport()\"]');\r\n      const canEdit = reportGenerated && currentStudent && !currentSessionLocked;\r\n      if (saveReportBtn) saveReportBtn.disabled = !canEdit;\r\n      if (lockBtn) lockBtn.disabled = !currentReportCardId || currentSessionLocked;\r\n      if (printBtn) printBtn.disabled = !(reportGenerated && currentStudent);\r\n    };\r\n\r\n    window.showStatus = (elementId, message, type) => {\r\n      const statusEl = document.getElementById(elementId);\r\n      const icon = type === 'success'\r\n        ? '<svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>'\r\n        : '<svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"8\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"16\" x2=\"12.01\" y2=\"16\"/></svg>';\r\n      statusEl.innerHTML = `<div class=\"save-status ${type}\">${icon}<span>${message}</span></div>`;\r\n      setTimeout(() => {\r\n        statusEl.innerHTML = '';\r\n      }, 5000);\r\n    };\r\n\r\n    document.addEventListener('DOMContentLoaded', () => {\r\n      if (!document.querySelector('.subject-row')) addSubject();\r\n      updateStats();\r\n      updateCardStatus();\r\n      updateSaveReportButton();\r\n    });\r\n  "},{"attributes":{"type":"module","src":"access-control.js"},"text":""},{"attributes":{"src":"schoolix-polish.js"},"text":""},{"attributes":{"src":"admin-shell.js?v=navbar-20260721"},"text":""}]};
